model:
rachana: 1
sutra: filing-feed
version: 1
description: 
match: { kind: filing-feed, priority: 10 }
title: { pill: "US equities · EDGAR filings", id: "$.FEED", with: "$.NAME" }
strip:
  - { label: "Forms", bind: "$.NAME" }
  - { label: "Filings", bind: "$.FILINGS", emphasis: true }
  - { label: "Companies", bind: "$.COMPANIES" }
  - { label: "Latest", bind: "$.LATEST", fmt: "date" }
  - { label: "Earliest shown", bind: "$.EARLIEST", fmt: "date" }
panels:
  - id: feed
    kind: table
    title: "Latest filings (a click opens one beside)"
    key: "F2"
    code: "FIL"
    rows: "$.ROWS"
    empty: "No filings"
    columns:
      - { label: "Filed", bind: "@.FILED", fmt: "date" }
      - { label: "Form", bind: "@.FORM" }
      - { label: "What it is", bind: "@.DESCRIPTION" }
      - { label: "Company", bind: "@.COMPANY_NAME" }
      - { label: "Accession", bind: "@.ACCESSION" }
  - id: by
    kind: hbar
    title: "Filings by form or company"
    key: "F3"
    area: right
    phone: { tier: "glance", from: "fragment", rows: 5 }
    rows: "$.BY"
    label: "LABEL"
    value: "VALUE"
    fmt: "amount0"
  - id: forms
    kind: kv
    title: "Browse by form"
    area: right
    columns:
      - { label: "Every form", bind: "link('ALL', 'filing-feed', 'EDGAR ALL')" }
      - { label: "Annual reports", bind: "link('10-K', 'filing-feed', 'EDGAR 10-K')" }
      - { label: "Quarterly reports", bind: "link('10-Q', 'filing-feed', 'EDGAR 10-Q')" }
      - { label: "Current reports", bind: "link('8-K', 'filing-feed', 'EDGAR 8-K')" }
      - { label: "Insider transactions", bind: "link('4', 'filing-feed', 'EDGAR 4')" }
      - { label: "Proxy statements", bind: "link('DEF-14A', 'filing-feed', 'EDGAR DEF-14A')" }
  - id: source
    kind: kv
    title: "Data source and licence"
    area: right
    phone: { tier: "must", from: "fragment" }
    rows: "$.PROVENANCE"
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
keys: { F9: "raw" }
